export type IconName = (keyof typeof iconData) extends never
  ? string
  : keyof typeof iconData;
export const iconNames = Object.keys(iconData) as IconName[];
export const getIconData = (name: IconName): IconDefinition | undefined =>
  (iconData as Record<string, IconDefinition>)[name];
